_id']);click(controls['load']) click(controls['preview']);assert not warnings,warnings assert not service.open_project('P')['boq'] controls['reviewer'].setText('بازبین مستقل مصنوعی') controls['note'].setText('کنترل داده مصنوعی با فرم اصلی') click(controls['review']);assert not warnings,warnings assert not service.open_project('P')['boq'] click(controls['commit']);assert not warnings,warnings record=service.get_aec_system('P',family,'L1',specimen['system_id']) assert record['status']=='committed' assert service.open_project('P')['boq'] seen.append(family) except Exception as exc:errors.append(exc) finally: if modal is not None:modal.reject() timer=QTimer(wizard);timer.setSingleShot(True);timer.timeout.connect(complete_modal) try: click(wizard.preview_button);assert wizard.active is not None timer.start(30);click(wizard.open_form_button) > assert not errors,errors E AssertionError: [AssertionError("['تغییرات ابتدا باید ذخیره شوند'] E assert not ['تغییرات ابتدا باید ذخیره شوند']")] E assert not [AssertionError("['تغییرات ابتدا باید ذخیره شوند']\nassert not ['تغییرات ابتدا باید ذخیره شوند']")]
